__vector__ __global__ void add_custom(__gm__ float* x, __gm__ float* y, __gm__ float* z)
{
    asc_init();
    constexpr uint32_t len = TOTAL_LENGTH / NUM_BLOCKS;
    __ubuf__ float xl[len], yl[len], zl[len];

    asc_copy_gm2ub(xl, x + block_idx * len, len * sizeof(float));
    asc_sync();                       // 等搬完，否则读到垃圾

    asc_add(zl, xl, yl, len);
    asc_sync();                       // 等算完，否则写回半成品

    asc_copy_ub2gm(z + block_idx * len, zl, len * sizeof(float));
}
